CREATE TABLE sessions (id TEXT PRIMARY KEY, player_name TEXT NOT NULL, scenario_id TEXT NOT NULL, game_state_json TEXT NOT NULL, mission_state_json TEXT NOT NULL, relationship_trust REAL NOT NULL DEFAULT 0.5, created_at TIMESTAMP NOT NULL);
CREATE TABLE messages (id TEXT PRIMARY KEY, session_id TEXT NOT NULL REFERENCES sessions(id), role TEXT NOT NULL, content TEXT NOT NULL, created_at TIMESTAMP NOT NULL);
CREATE TABLE memories (id TEXT PRIMARY KEY, session_id TEXT NOT NULL REFERENCES sessions(id), claim_key TEXT NOT NULL, claim_text TEXT NOT NULL, subject TEXT NOT NULL, predicate TEXT NOT NULL, value TEXT NOT NULL, source_type TEXT NOT NULL, source_id TEXT, confidence REAL NOT NULL, status TEXT NOT NULL, created_at TIMESTAMP NOT NULL);
CREATE TABLE conflicts (id TEXT PRIMARY KEY, session_id TEXT NOT NULL REFERENCES sessions(id), memory_a_id TEXT NOT NULL REFERENCES memories(id), memory_b_id TEXT NOT NULL REFERENCES memories(id), status TEXT NOT NULL, resolution_note TEXT, created_at TIMESTAMP NOT NULL);
